96				padding-top: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-top));
97				padding-right: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-right));
98				padding-bottom: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-bottom));
