116				line-height: 1.2;
117				text-wrap: balance;
118				margin: 2rem 0 1rem 0;
119				letter-spacing: -0.01em;
120			}
121			h2:first-child {
122				margin-top: 0;
123			}
124			p {
125				text-wrap: pretty;
126				margin: 1rem 0;
127				line-height: 1.65;
128			}
