265				position: absolute;
266				width: 1px;
267				height: 1px;
268				margin: -1px;
269				padding: 0;
270				overflow: hidden;
271				clip: rect(0, 0, 0, 0);
272				clip-path: inset(50%);
273				white-space: nowrap;
274				border: 0;
275			}
276			@media (prefers-contrast: more) {
277				:root {
278					--border: currentColor;
279					--border-control: currentColor;
280				}
281				button,
282				.button {
283					border-width: 3px;
284				}
285				.card {
286					border-width: 2px;
287				}
288			}
289			footer {
290				padding-block: 1.5rem;
291				border-top: 1px solid var(--border);
292				font-size: 0.875rem;
293				color: var(--text-secondary);
294				text-align: center;
295			}
296			footer p {
297				margin: 0.5rem 0;
298			}
299			small {
300				display: block;
301			}
302			kbd {
303				background: var(--surface);
304				border: 1px solid var(--border);
305				border-radius: 0.25rem;
306				padding: 0.125rem 0.375rem;
307				font-family: monospace;
308				font-size: 0.875em;
309			}
310			.field {
311				margin-bottom: 1rem;
312			}
313			label {
314				display: block;
315				margin-bottom: 0.5rem;
316				font-weight: 500;
317			}
318			input,
319			textarea {
320				width: 100%;
321				padding: 0.5rem;
322				font: inherit;
323				color: var(--text);
324				background: var(--surface);
325				border: 1px solid var(--border-control);
326				border-radius: 0.25rem;
327			}
328			textarea {
329				resize: vertical;
330			}
331			#form-status {
332				margin: 0;
333			}
334			#form-status:not(:empty) {
335				margin-top: 1rem;
336				padding: 0.75rem 1rem;
337				border-radius: 0.25rem;
338				background: color-mix(in srgb, var(--success) 10%, transparent);
339				color: var(--success);
340				border: 1px solid var(--success);
341			}
342			.form-hint {
343				margin: 0 0 1rem 0;
344				font-size: 0.875rem;
345				color: var(--text-secondary);
346			}
347			.field .form-hint {
348				margin: 0.25rem 0 0 0;
349			}
