355				display: block;
356				color: var(--error);
357				font-size: 0.875rem;
358				font-weight: 500;
359			}
360			.error-message:not(:empty) {
361				margin-top: 0.25rem;
362			}
363			.counter {
364				display: flex;
365				flex-wrap: wrap;
366				gap: 1rem;
367				align-items: center;
368				margin: 1.5rem 0;
369			}
