394				border-color: var(--accent);
395			}
396			@media print {
397				:root {
398					color-scheme: light;
399					--text: #000;
400					--text-secondary: #333;
401					--background: #fff;
402					--surface: #fff;
403					--accent: #000;
404					--border: #999;
405					--border-control: #000;
406					--error: #000;
407					--success: #000;
