409				.skip-link,
410				nav,
411				button,
412				.button,
413				.live-region {
414					display: none;
415				}
416				body {
417					display: block;
418					min-height: 0;
419					max-width: none;
420					padding: 0;
421				}
422				a {
423					color: inherit;
424					text-decoration: underline;
425				}
426				a[href^="http"]::after {
427					content: " (" attr(href) ")";
428					font-size: 0.85em;
