432					border: none;
433					break-inside: avoid;
434				}
435			}
436		</style>
437	</head>
438	<body>
439		<a class="skip-link" href="#main">Skip to content</a>
440		<header id="top">
441			<h1>Welcome</h1>
442			<nav aria-label="Page sections">
443				<ul>
444					<li><a href="#features">Features</a></li>
445					<li><a href="#examples">Examples</a></li>
446					<li><a href="#resources">Resources</a></li>
447				</ul>
448			</nav>
449		</header>
450		<main id="main" tabindex="-1">
451			<section aria-label="Introduction">
452				<p>This is a well-structured, accessible HTML5 document demonstrating modern best practices for semantic markup and inclusive design.</p>
453				<p>
454					It uses semantic landmarks, a skip link for keyboard navigation,
455					and CSS that adapts to your light or dark mode preference.
456				</p>
457				<p>
458					Text and link colors meet WCAG AA contrast in both themes, type scales
459					with your browser's font size, and motion respects your system settings.
460				</p>
461			</section>
462	
463			<section aria-labelledby="features">
464				<h2 id="features">Features</h2>
465				<ul>
466					<li>Semantic HTML structure with proper landmarks</li>
467					<li>Keyboard accessible navigation and focus management</li>
468					<li>Dark mode support with custom color schemes</li>
469					<li>Responsive typography using modern CSS</li>
470					<li>Print-friendly styles for better readability</li>
471					<li>WCAG AA contrast compliance in all color modes</li>
472				</ul>
473			</section>
474	
475			<section aria-labelledby="examples">
476				<h2 id="examples">Examples</h2>
477				<article class="card">
478					<h3>Component Cards</h3>
479					<p>Card components are useful for organizing related content. They include a subtle border and padding for visual separation.</p>
480					<a class="button" href="#resources">Learn more<span class="visually-hidden"> about accessibility resources</span></a>
481				</article>
482	
483				<article class="card">
484					<h3>Interactive Elements</h3>
485					<p>Buttons and links are fully accessible with clear focus states. All interactive elements include visible focus indicators and proper ARIA labels.</p>
486					<p><strong>Keyboard navigation:</strong> Use <kbd>Tab</kbd> to move forward, <kbd>Shift</kbd>+<kbd>Tab</kbd> to move backward, and <kbd>Enter</kbd> to activate.</p>
487				</article>
488	
489				<article class="card">
490					<h3>Accessible Form</h3>
491					<form id="contact-form" novalidate>
492						<p class="form-hint">Fields marked * are required.</p>
493						<div class="field">
494							<label for="email">Email <span aria-hidden="true">*</span></label>
495							<input type="email" id="email" name="email" autocomplete="email" spellcheck="false" autocapitalize="none" required aria-describedby="email-help">
496							<span id="email-error" class="error-message"></span>
497							<small id="email-help" class="form-hint">For example, name@example.com</small>
498						</div>
499						<div class="field">
500							<label for="message">Message</label>
501							<textarea id="message" name="message" rows="4" maxlength="2000" aria-describedby="message-help"></textarea>
502							<small id="message-help" class="form-hint">Up to 2,000 characters.</small>
503						</div>
504						<button type="submit">Send message</button>
505						<p id="form-status" role="status"></p>
506					</form>
507				</article>
508	
509				<article class="card">
510					<h3>Live Region Example</h3>
511					<p>Click the button to announce a message using a live region. This demonstrates how screen readers are notified of dynamic updates.</p>
512					<button id="announce" type="button">Announce message</button>
513					<div class="live-region" aria-live="polite" aria-atomic="true">
514						<span id="live-message"></span>
515					</div>
516				</article>
517	
518				<article class="card">
519					<h3>Interactive Counter</h3>
520					<p>This counter demonstrates state management and ARIA live regions for accessible dynamic content.</p>
521					<div class="counter">
522						<button id="decrease" type="button" aria-label="Decrease count by 1">−</button>
523						<output id="count" aria-live="off">0</output>
524						<button id="increase" type="button" aria-label="Increase count by 1">+</button>
525						<button id="reset" type="button" aria-label="Reset count to zero">Reset</button>
526					</div>
527					<div class="live-region" aria-live="polite" aria-atomic="true">
528						<span id="count-message"></span>
529					</div>
530				</article>
531			</section>
532	
533			<section aria-labelledby="resources">
534				<h2 id="resources">Resources</h2>
535				<p>Want to learn more about web accessibility and semantic HTML? Check out these resources:</p>
536				<ul>
537					<li><a href="https://www.w3.org/WAI/WCAG22/quickref/" target="_blank" rel="noopener noreferrer">WCAG 2.2 Quick Reference<span class="visually-hidden"> (opens in new tab)</span></a></li>
538					<li><a href="https://html.spec.whatwg.org/" target="_blank" rel="noopener noreferrer">HTML Living Standard<span class="visually-hidden"> (opens in new tab)</span></a></li>
539					<li><a href="https://www.a11y-101.com/" target="_blank" rel="noopener noreferrer">A11y 101<span class="visually-hidden"> (opens in new tab)</span></a></li>
540				</ul>
541			</section>
542		</main>
543		<footer>
544			<nav aria-label="Footer links">
545				<ul>
546					<li><a href="#top">Back to top</a></li>
547					<li><a href="https://github.com" target="_blank" rel="noopener noreferrer">GitHub<span class="visually-hidden"> (opens in new tab)</span></a></li>
548				</ul>
549			</nav>
550			<p><small>&copy; <span id="copyright-year">2026</span>. All rights reserved.</small></p>
551		</footer>
552		<script>
553			const copyrightYear = document.getElementById('copyright-year');
554			if (copyrightYear) {
555				copyrightYear.textContent = String(new Date().getFullYear());
556			}
557	
558			const messages = [
559				"This update was announced to screen readers!",
560				"Dynamic content updates work with aria-live regions.",
561				"Live regions are essential for accessible web apps.",
562				"Try this with a screen reader like NVDA or JAWS!"
563			];
564			let nextMessage = 0;
565			let count = 0;
566			const announceBtn = document.getElementById('announce');
567			const liveMessage = document.getElementById('live-message');
568			const contactForm = document.getElementById('contact-form');
569			const emailInput = document.getElementById('email');
570			const formStatus = document.getElementById('form-status');
571			const countDisplay = document.getElementById('count');
572			const countMessage = document.getElementById('count-message');
573			const decreaseBtn = document.getElementById('decrease');
574			const increaseBtn = document.getElementById('increase');
575			const resetBtn = document.getElementById('reset');
576	
577			const updateCountDisplay = () => {
578				countDisplay.textContent = count;
579				countMessage.textContent = `Count is now ${count}.`;
580			};
581	
582			if (countDisplay && countMessage) {
583				decreaseBtn?.addEventListener('click', () => {
584					count--;
585					updateCountDisplay();
586				});
587	
588				increaseBtn?.addEventListener('click', () => {
589					count++;
590					updateCountDisplay();
591				});
592	
593				resetBtn?.addEventListener('click', () => {
594					count = 0;
595					updateCountDisplay();
596				});
597			}
598	
599			if (announceBtn && liveMessage) {
600				announceBtn.addEventListener('click', () => {
601					liveMessage.textContent = messages[nextMessage];
602					nextMessage = (nextMessage + 1) % messages.length;
603				});
604			}
605	
606			if (contactForm) {
607				const emailError = document.getElementById('email-error');
608	
609				const validateEmail = () => {
610					let message = '';
611					if (emailInput.validity.valueMissing) {
612						message = 'Enter your email address.';
613					} else if (!emailInput.validity.valid) {
614						message = 'Enter an email address in the format name@example.com.';
615					}
616					emailError.textContent = message;
617					if (message) {
618						emailInput.setAttribute('aria-invalid', 'true');
619						emailInput.setAttribute('aria-describedby', 'email-error email-help');
620					} else {
621						emailInput.removeAttribute('aria-invalid');
622						emailInput.setAttribute('aria-describedby', 'email-help');
623					}
624					return !message;
625				};
626	
627				emailInput.addEventListener('blur', () => {
628					if (emailInput.value || emailInput.hasAttribute('aria-invalid')) {
629						validateEmail();
630					}
631				});
632	
633				emailInput.addEventListener('input', () => {
634					if (emailInput.hasAttribute('aria-invalid')) {
635						validateEmail();
636					}
637				});
638	
639				contactForm.addEventListener('input', () => {
640					formStatus.textContent = '';
